CREATE TABLE IF NOT EXISTS reliability_runs (id INTEGER PRIMARY KEY AUTOINCREMENT,experiment_id INTEGER NOT NULL,source_type TEXT NOT NULL,window_code TEXT NOT NULL,window_start TEXT,window_end TEXT NOT NULL,calculation_version TEXT NOT NULL,status TEXT NOT NULL,resolved_n INTEGER NOT NULL,created_at TEXT NOT NULL,UNIQUE(experiment_id,source_type,window_code,window_end,calculation_version),FOREIGN KEY(experiment_id) REFERENCES experiments(id));
CREATE TABLE IF NOT EXISTS reliability_scores (id INTEGER PRIMARY KEY AUTOINCREMENT,reliability_run_id INTEGER NOT NULL UNIQUE,fps REAL,ecs REAL,frs REAL,direction_score REAL,probability_score REAL,calibration_score REAL,return_error_score REAL,benchmark_edge_score REAL,consistency_score REAL,sample_size_score REAL,time_coverage_score REAL,coverage_score REAL,regime_coverage_score REAL,data_quality_score REAL,raw_accuracy REAL,balanced_accuracy REAL,brier_score REAL,ece REAL,mean_scaled_error REAL,primary_edge_pp REAL,ci95_low REAL,ci95_high REAL,fps_label TEXT,ecs_label TEXT,frs_label TEXT,trend_label TEXT,trend_confidence TEXT,diagnostics_json TEXT NOT NULL,created_at TEXT NOT NULL,FOREIGN KEY(reliability_run_id) REFERENCES reliability_runs(id));
CREATE TABLE IF NOT EXISTS reliability_group_scores (id INTEGER PRIMARY KEY AUTOINCREMENT,reliability_run_id INTEGER NOT NULL,group_type TEXT NOT NULL,group_key TEXT NOT NULL,resolved_n INTEGER NOT NULL,fps REAL,ecs REAL,frs REAL,balanced_accuracy REAL,raw_accuracy REAL,diagnostics_json TEXT,UNIQUE(reliability_run_id,group_type,group_key),FOREIGN KEY(reliability_run_id) REFERENCES reliability_runs(id));
CREATE TABLE IF NOT EXISTS forecast_regimes (id INTEGER PRIMARY KEY AUTOINCREMENT,final_prediction_id INTEGER NOT NULL UNIQUE,regime_code TEXT NOT NULL,classifier_version TEXT NOT NULL,classified_at TEXT NOT NULL,metadata_json TEXT,FOREIGN KEY(final_prediction_id) REFERENCES final_predictions(id));
CREATE INDEX IF NOT EXISTS idx_reliability_lookup ON reliability_runs(experiment_id,source_type,window_code,window_end);
CREATE INDEX IF NOT EXISTS idx_final_predictions_experiment_source ON final_predictions(experiment_id,source_type,generated_at);
CREATE INDEX IF NOT EXISTS idx_actual_outcomes_time ON actual_outcomes(actual_price_time);
CREATE INDEX IF NOT EXISTS idx_eval_prediction ON evaluation_results(final_prediction_id);
